), retired AS (
  SELECT owner.id, item.key
  FROM policy_packs AS owner,
    json_each(CASE WHEN json_valid(owner.definition) THEN owner.definition ELSE '{}' END,
      '$.cronPolicy.cronTemplates') AS item
  WHERE item.type = 'object' AND EXISTS (
    SELECT 1 FROM defaults
    WHERE NOT EXISTS (
      SELECT fullkey, type, atom FROM json_tree(item.value)
      EXCEPT SELECT fullkey, type, atom FROM json_tree(defaults.value)
    ) AND NOT EXISTS (
      SELECT fullkey, type, atom FROM json_tree(defaults.value)
      EXCEPT SELECT fullkey, type, atom FROM json_tree(item.value)
    )
  )
)
UPDATE policy_packs AS owner
SET definition = json_set(owner.definition, '$.cronPolicy.cronTemplates', json((
  SELECT json_group_array(json(kept.value))
  FROM (
    SELECT owner.definition -> ('$.cronPolicy.cronTemplates[' || item.key || ']') AS value
    FROM json_each(owner.definition, '$.cronPolicy.cronTemplates') AS item
    WHERE NOT EXISTS (
      SELECT 1 FROM retired WHERE retired.id = owner.id AND retired.key = item.key
    )
    ORDER BY CAST(item.key AS INTEGER)
  ) AS kept
)))
WHERE id IN (SELECT id FROM retired)
  AND json_type(definition, '$.cronPolicy.cronTemplates') = 'array';

